class StatementExistenceInputCompositionTest {
	@Test
	void nativeExistenceProbeMaterializesTheSameRequestParametersAsIteration() {
		SimpleValueFactory vf = SimpleValueFactory.getInstance();
		IRI present = vf.createIRI("urn:test:present");
		IRI missing = vf.createIRI("urn:test:missing");
		IRI predicate = vf.createIRI("urn:test:predicate");
		Statement only = vf.createStatement(present, predicate, vf.createLiteral("value"));
		TripleSource source = new TripleSource() {
			@Override
			public ValueFactory getValueFactory() {
				return vf;
			}

			@Override
			public CloseableIteration<? extends Statement> getStatements(Resource subject, IRI pred, Value object,
					Resource... contexts) {
				boolean matches = (subject == null || subject.equals(only.getSubject()))
						&& (pred == null || pred.equals(only.getPredicate()))
						&& (object == null || object.equals(only.getObject()));
				return new CloseableIteratorIteration<>(
						matches ? List.of(only).iterator() : List.<Statement>of().iterator());
			}
		};
		for (Resource subject : List.of(missing, present)) {
			QueryBindingSet raw = new QueryBindingSet();
			raw.addBinding("s", subject);
			StatementPattern pattern = new StatementPattern(Var.of("s"), Var.of("p", predicate), Var.of("o"));
			new BindingAssignerOptimizer().optimize(pattern, null, raw);
			assertTrue(pattern.getSubjectVar().hasApiInputOrigin());
			assertEquals(subject, pattern.getSubjectVar().getValue());
			StatementPatternQueryEvaluationStep step = new StatementPatternQueryEvaluationStep(pattern,
					new QueryEvaluationContext.Minimal((Dataset) null), source);
			BindingSet parameters = BindingSetOrigin.optimizationInput(raw);
			assertFalse(parameters.hasBinding("s"));
			boolean iterated;
			try (CloseableIteration<BindingSet> rows = step.evaluate(parameters)) {
				iterated = rows.hasNext();
			}
			assertEquals(subject.equals(present), iterated);
			assertEquals(iterated, step.hasStatement(parameters));
		}
	}

	@Test
	void inheritedGraphSelectorMismatchDeclinesTheProbeExactlyLikeIteration() {
		SimpleValueFactory vf = SimpleValueFactory.getInstance();
		IRI selectedGraph = vf.createIRI("urn:test:selected-graph");
		IRI otherGraph = vf.createIRI("urn:test:other-graph");
		IRI predicate = vf.createIRI("urn:test:predicate");
		Statement only = vf.createStatement(vf.createIRI("urn:test:subject"), predicate,
				vf.createLiteral("value"), selectedGraph);
		TripleSource source = new TripleSource() {
			@Override
			public ValueFactory getValueFactory() {
				return vf;
			}

			@Override
			public CloseableIteration<? extends Statement> getStatements(Resource subject, IRI pred, Value object,
					Resource... contexts) {
				boolean matches = (subject == null || subject.equals(only.getSubject()))
						&& (pred == null || pred.equals(only.getPredicate()))
						&& (object == null || object.equals(only.getObject()))
						&& (contexts.length == 0 || List.of(contexts).contains(selectedGraph));
				return new CloseableIteratorIteration<>(
						matches ? List.of(only).iterator() : List.<Statement>of().iterator());
			}
		};
		StatementPattern pattern = new StatementPattern(StatementPattern.Scope.NAMED_CONTEXTS, Var.of("s"),
				Var.of("p", predicate), Var.of("o"), Var.of("g", selectedGraph));
		pattern.setContextBindingOriginInherited(true);
		StatementPatternQueryEvaluationStep step = new StatementPatternQueryEvaluationStep(pattern,
				new QueryEvaluationContext.Minimal((Dataset) null), source);
		for (Resource suppliedGraph : List.of(otherGraph, selectedGraph)) {
			QueryBindingSet input = new QueryBindingSet();
			input.addBinding("g", suppliedGraph);
			boolean iterated;
			try (CloseableIteration<BindingSet> rows = step.evaluate(input)) {
				iterated = rows.hasNext();
			}
			assertEquals(suppliedGraph.equals(selectedGraph), iterated);
			assertEquals(iterated, step.hasStatement(input));
		}
	}
}
